('bmlt-biostatistics-research-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',2701,$json${"question":"Accuracy describes how close a measurement is to","translation":"","options":["The true or accepted value","The same result on repeated testing only","The detection limit","The reference interval"],"correctIndex":0,"explanation":"Accuracy is closeness to the true or accepted reference value.","explanationNe":"Accuracy भनेको मापनको नतिजा वास्तविक वा स्वीकार्य मानसँग कति नजिक छ भन्ने हो।","topic":"Accuracy and precision"}$json$::jsonb,true),
('bmlt-biostatistics-research-mcq-002','BMLT','BMLT NHPC Licensing','mcq','free',2702,$json${"question":"Precision refers to","translation":"","options":["Closeness of repeated measurements to one another","Closeness to the true value only","The ability to detect disease","The width of a reference interval"],"correctIndex":0,"explanation":"Precision describes repeatability or agreement among repeated measurements.","explanationNe":"Precision भनेको पटकपटक गरिएको मापनको नतिजा आपसमा कति मिल्छ भन्ने हो।","topic":"Accuracy and precision"}$json$::jsonb,true),
('bmlt-biostatistics-research-mcq-003','BMLT','BMLT NHPC Licensing','mcq','free',2703,$json${"question":"A method gives very similar results each time, but all are far from the true value. It is","translation":"","options":["Precise but inaccurate","Accurate and precise","Accurate but imprecise","Neither precise nor repeatable"],"correctIndex":0,"explanation":"Consistent results indicate precision, while systematic deviation indicates poor accuracy.","explanationNe":"नतिजा आपसमा मिल्नु precision हो; वास्तविक मानबाट टाढा हुनु accuracy कम हुनु हो।","topic":"Accuracy and precision"}$json$::jsonb,true),
('bmlt-biostatistics-research-mcq-004','BMLT','BMLT NHPC Licensing','mcq','free',2704,$json${"question":"A systematic error is best described as","translation":"","options":["A consistent bias in one direction","Random variation around the mean","A clerical spelling mistake only","A change in patient age"],"correctIndex":0,"explanation":"Systematic error introduces a reproducible bias into measurements.","explanationNe":"Systematic error ले नतिजामा एउटै दिशाको निरन्तर bias ल्याउँछ।","topic":"Laboratory errors"}$json$::jsonb,true),
