('bmlt-biostatistics-research-mcq-007','BMLT','BMLT NHPC Licensing','mcq','free',2707,$json${"question":"The median is","translation":"","options":["The middle value after arranging observations in order","The most frequent value","The arithmetic average","The difference between maximum and minimum"],"correctIndex":0,"explanation":"The median divides ordered observations into two equal halves.","explanationNe":"Median भनेको मानहरू क्रमबद्ध गरेपछि बीचमा पर्ने मान हो।","topic":"Descriptive statistics"}$json$::jsonb,true),
('bmlt-biostatistics-research-mcq-008','BMLT','BMLT NHPC Licensing','mcq','free',2708,$json${"question":"The mode is","translation":"","options":["The most frequently occurring value","The middle value","The sum of all values","The square root of variance"],"correctIndex":0,"explanation":"Mode identifies the most common observation.","explanationNe":"Mode भनेको सबैभन्दा धेरै पटक देखिएको मान हो।","topic":"Descriptive statistics"}$json$::jsonb,true),
('bmlt-biostatistics-research-mcq-009','BMLT','BMLT NHPC Licensing','mcq','free',2709,$json${"question":"Which measure of central tendency is least affected by extreme outliers?","translation":"","options":["Median","Mean","Range","Standard deviation"],"correctIndex":0,"explanation":"The median is resistant to extreme values compared with the mean.","explanationNe":"Extreme outlier ले mean भन्दा median लाई कम असर गर्छ।","topic":"Descriptive statistics"}$json$::jsonb,true),
('bmlt-biostatistics-research-mcq-010','BMLT','BMLT NHPC Licensing','mcq','free',2710,$json${"question":"Range is calculated as","translation":"","options":["Maximum value minus minimum value","Mean divided by median","Sum divided by sample size","Variance squared"],"correctIndex":0,"explanation":"Range measures the spread between the largest and smallest observations.","explanationNe":"Range = सबैभन्दा ठूलो मान − सबैभन्दा सानो मान।","topic":"Dispersion"}$json$::jsonb,true),
('bmlt-biostatistics-research-mcq-011','BMLT','BMLT NHPC Licensing','mcq','free',2711,$json${"question":"Standard deviation describes","translation":"","options":["Spread of observations around the mean","The most frequent observation","The number of positive tests","The accuracy of patient identification"],"correctIndex":0,"explanation":"Standard deviation quantifies dispersion around the mean.","explanationNe":"Standard deviation ले mean वरिपरि नतिजा कति फैलिएका छन् भन्ने देखाउँछ।","topic":"Dispersion"}$json$::jsonb,true),
('bmlt-biostatistics-research-mcq-012','BMLT','BMLT NHPC Licensing','mcq','free',2712,$json${"question":"A small standard deviation generally indicates","translation":"","options":["Measurements are clustered close to the mean","Measurements are widely scattered","The method is necessarily accurate","All results are clinically normal"],"correctIndex":0,"explanation":"A smaller SD indicates less dispersion, not necessarily accuracy.","explanationNe":"सानो SD ले नतिजा mean नजिक छन् भन्ने देखाउँछ, तर accuracy स्वतः प्रमाणित गर्दैन।","topic":"Dispersion"}$json$::jsonb,true),
('bmlt-biostatistics-research-mcq-013','BMLT','BMLT NHPC Licensing','mcq','free',2713,$json${"question":"The coefficient of variation is calculated as","translation":"","options":["SD divided by mean, multiplied by 100","Mean divided by SD, multiplied by 100","Range divided by median","Mean plus SD"],"correctIndex":0,"explanation":"CV expresses SD relative to the mean as a percentage.","explanationNe":"CV = SD ÷ mean × 100 हो।","topic":"Dispersion"}$json$::jsonb,true),
('bmlt-biostatistics-research-mcq-014','BMLT','BMLT NHPC Licensing','mcq','free',2714,$json${"question":"Coefficient of variation is particularly useful for","translation":"","options":["Comparing relative imprecision between methods or analytes","Identifying a patient's blood group","Calculating sensitivity directly","Replacing internal quality control"],"correctIndex":0,"explanation":"CV allows comparison of variability relative to different mean concentrations.","explanationNe":"CV ले फरक mean भएका परीक्षणको relative variability तुलना गर्न मद्दत गर्छ।","topic":"Dispersion"}$json$::jsonb,true),
