('bmlt-biostatistics-research-mcq-016','BMLT','BMLT NHPC Licensing','mcq','free',2716,$json${"question":"In a normal distribution, approximately what proportion of values lies within ±2 SD?","translation":"","options":["95%","50%","68%","99.99%"],"correctIndex":0,"explanation":"About 95% of values lie within two standard deviations of the mean.","explanationNe":"Normal distribution मा करिब ९५% मान ±2 SD भित्र पर्छन्।","topic":"Distributions"}$json$::jsonb,true),
('bmlt-biostatistics-research-mcq-017','BMLT','BMLT NHPC Licensing','mcq','free',2717,$json${"question":"A reference interval commonly covers which central proportion of a healthy reference population?","translation":"","options":["95%","50%","68%","100%"],"correctIndex":0,"explanation":"Many laboratory reference intervals are defined using the central 95% of a reference population.","explanationNe":"धेरै laboratory reference interval स्वस्थ reference population को बीचका ९५% मानमा आधारित हुन्छन्।","topic":"Reference intervals"}$json$::jsonb,true),
('bmlt-biostatistics-research-mcq-018','BMLT','BMLT NHPC Licensing','mcq','free',2718,$json${"question":"A p-value of 0.03 means, under the null hypothesis and model assumptions,","translation":"","options":["The probability of data this extreme or more extreme is 3%","There is a 97% probability the alternative hypothesis is true","The result is clinically important in every case","There is a 3% probability the null hypothesis is true"],"correctIndex":0,"explanation":"A p-value is a tail probability under the null hypothesis, not the probability that a hypothesis is true.","explanationNe":"p-value भनेको null hypothesis सही मान्दा यस्तो वा अझ extreme data आउने सम्भावना हो।","topic":"Hypothesis testing"}$json$::jsonb,true),
('bmlt-biostatistics-research-mcq-019','BMLT','BMLT NHPC Licensing','mcq','free',2719,$json${"question":"A Type I error occurs when a researcher","translation":"","options":["Rejects a true null hypothesis","Fails to reject a false null hypothesis","Uses a large sample","Measures the same sample twice"],"correctIndex":0,"explanation":"Type I error is a false-positive statistical conclusion.","explanationNe":"Type I error भनेको सही null hypothesis लाई गलत रूपमा अस्वीकार गर्नु हो।","topic":"Hypothesis testing"}$json$::jsonb,true),
('bmlt-biostatistics-research-mcq-020','BMLT','BMLT NHPC Licensing','mcq','free',2720,$json${"question":"A Type II error occurs when a researcher","translation":"","options":["Fails to reject a false null hypothesis","Rejects a true null hypothesis","Uses a random sample","Obtains a small p-value"],"correctIndex":0,"explanation":"Type II error is a false-negative statistical conclusion.","explanationNe":"Type II error भनेको गलत null hypothesis अस्वीकार गर्न असफल हुनु हो।","topic":"Hypothesis testing"}$json$::jsonb,true),
('bmlt-biostatistics-research-mcq-021','BMLT','BMLT NHPC Licensing','mcq','free',2721,$json${"question":"Statistical power is the probability of","translation":"","options":["Correctly rejecting a false null hypothesis","Making a Type I error","Obtaining a normal distribution","Selecting every eligible participant"],"correctIndex":0,"explanation":"Power equals one minus the probability of Type II error.","explanationNe":"Statistical power भनेको गलत null hypothesis सही रूपमा अस्वीकार गर्ने सम्भावना हो।","topic":"Hypothesis testing"}$json$::jsonb,true),
('bmlt-biostatistics-research-mcq-022','BMLT','BMLT NHPC Licensing','mcq','free',2722,$json${"question":"Sensitivity is the proportion of","translation":"","options":["People with disease who test positive","People without disease who test negative","All positive results that are true positives","All negative results that are false negatives"],"correctIndex":0,"explanation":"Sensitivity measures the true-positive rate among people with disease.","explanationNe":"Sensitivity भनेको रोग भएका व्यक्तिमध्ये test positive आउने अनुपात हो।","topic":"Diagnostic test evaluation"}$json$::jsonb,true),
